    distinct_groups = []

    # Iterate through the input string and identify nested parentheses groups
    start = 0
    stack = []
    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                start = stack.pop()
                group = paren_string[start:i+1]

                # Check if each identified group is balanced
                if is_balanced(group):
                    distinct_groups.append(group)

    # Return the list of distinct balanced groups
    return distinct_groups

def is_balanced(group: str) -> bool:
    stack = []
    for char in group:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return not stack

